style.css:
@-moz-document url("https://web.whatsapp.com") {
/*
	Style created by @i-naeem
	@name         Whatsapp Blurred
	@homepageURL  https://userstyles.org/styles/276700/whatsappblurred
	@author       Naeem
	@e-mail       nemoxhan@gmail.com
	@version      1.0
	@license      MIT
	@preprocessor stylish
	*/


	/* Blur all the chat item */
	didiv[role="listitem"] div[aria-selected="false"]{
    filter: blur(3px);
    transition: filter 50ms ease-in !important;
	}

	/* Remove the blur effect on hovering over the account */
	div[role="listitem"] div[aria-selected="false"]:hover{
    filter: blur(0px);
	}

	/* Remove the blur effect to the active chat.*/
	div[role="listitem"] div[aria-selected="true"] {
    	filter: blur(0px);
	}
}
